const issues = $('Get open issues').all();

const byNumber = (a, b) => a.json.number - b.json.number;
const hasLabel = (item, name) =>
  (item.json.labels || []).some(label => label.name === name);

return {
  inProgress: issues.filter(i => hasLabel(i, 'ai-in-progress')).sort(byNumber),
  inQueue: issues.filter(i => hasLabel(i, 'ai-fix')).sort(byNumber),
};

const labels = $input.all().map(item => item.json);

const aiFix = labels.find(l => l.name === 'ai-fix');
const aiInProgress = labels.find(l => l.name === 'ai-in-progress');
const aiNeedsHuman = labels.find(l => l.name === 'ai-needs-human');
const aiReview = labels.find(l => l.name === 'ai-review');

return {
  aiFixId: aiFix.id,
  aiInProgressId: aiInProgress.id,
  aiNeedsHumanId: aiNeedsHuman.id,
  aiReviewId: aiReview.id
};

