const issue = $('Select queued issue').first().json;

// "Always Output Data" can add an empty item, so keep only real rows
const previous = $('Get previous attempts').all()
  .map(i => i.json)
  .filter(r => r.attempt !== undefined && r.attempt !== null);

const attempt = previous.reduce((max, r) => Math.max(max, Number(r.attempt)), 0) + 1;

const number = Number(issue.number);
if (!Number.isInteger(number) || number <= 0) {
  throw new Error(`Invalid issue number: ${issue.number}`);
}

const slug = String(issue.title ?? '')
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

const base = slug ? `issue/${number}-${slug}` : `issue/${number}`;
const branchName = attempt === 1 ? base : `${base}-attempt-${attempt}`;

return [{ json: { ...issue, attempt, branch_name: branchName } }];

const issue = $('Branch name').first().json; // number, title, body, branch_name
const template = $('Prompt template').first().json.prompt_template;

if (!issue.title) throw new Error('Issue has no title');
if (!issue.branch_name) throw new Error('Issue has no branch_name');
if (!template.includes('\n')) {
  throw new Error('Template has no line breaks: it was probably pasted into a single-line field');
}

// Wrap in single quotes, escaping any single quote inside the text
const shellQuote = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";

const values = {
  ISSUE_NUMBER: String(issue.number),
  ISSUE_TITLE: issue.title,
  ISSUE_TITLE_SHELL: shellQuote(issue.title),
  BRANCH_NAME: issue.branch_name,
  ISSUE_BODY: (issue.body || '(no description)')
    .replace(/\r\n/g, '\n')
    .replace(/<\/issue-body>/gi, ''),
};

// Single pass, accepting {{NAME}} and [[NAME]]. Text inside the issue is never re-scanned.
const unknown = [];
let replaced = 0;
const prompt = template.replace(
  /\{\{\s*(\w+)\s*\}\}|\[\[\s*(\w+)\s*\]\]/g,
  (m, a, b) => {
    const key = a || b;
    if (!Object.hasOwn(values, key)) {
      unknown.push(key);
      return m;
    }
    replaced++;
    return values[key];
  }
);
if (unknown.length) {
  throw new Error(`Unknown placeholders in template: ${unknown.join(', ')}`);
}
if (replaced === 0) {
  throw new Error('Template contains no placeholders');
}

// Small version stamp so you can tell which template produced which run
let h = 5381;
for (const ch of template) h = ((h * 33) ^ ch.codePointAt(0)) >>> 0;

return [{ json: { ...issue, prompt, prompt_version: h.toString(16) } }];
